</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const long long MOD1 = 998244353;
const long long MOD2 = 1000000007;

long long readNumber() {
    long long num = 0;
    int sign = 1;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') sign = -1;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        num = (num << 1) + (num << 3) + (ch - '0');
        ch = getchar();
    }
    return num * sign;
}

long long n;
vector<int> buckets[10];
long long sumArr[10];
long long count1 = 0, count2 = 0, answer = 0;
int powArr[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

void generate(int length, long long val) {
    if (length > 6) return;
    buckets[length].push_back((count1 - val + MOD1) % MOD1);
    sumArr[length] += (count1 - val + MOD1) % MOD1;
    ++count1;
    for (int digit = 0; digit <= 9; ++digit) {
        generate(length + 1, val * 10 + digit);
    }
}

bool validRange(long long x) {
    return x * 1000000 + 999999 <= n && x * 10000000 > n;
}

void search(int length, long long val) {
    if (val > n) return;
    if (validRange(val)) {
        for (int i = 0; i <= 6; ++i) {
            long long v1 = ((count2 + 1 - val * powArr[i]) % MOD1 + MOD1) % MOD1;
            int idx = lower_bound(buckets[i].begin(), buckets[i].end(), (int)(MOD1 - v1)) - buckets[i].begin();
            answer = (answer + (sumArr[i] + buckets[i].size() * v1 - 1LL * MOD1 * (buckets[i].size() - idx))) % MOD2;
        }
        count2 += count1;
    } else {
        if (length) ++count2;
        answer = (answer + ((count2 - val) % MOD1 + MOD1) % MOD1) % MOD2;
        for (int digit = (!length); digit <= 9; ++digit) {
            search(length + 1, val * 10 + digit);
        }
    }
}

int main() {
    n = readNumber();
    generate(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(buckets[i].begin(), buckets[i].end());
    }
    search(0, 0);
    cout << answer << "\n";
    return 0;
}
